import { Controller, Get, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 설정 영역 고정값
const ASSET_AREA = '자산';
// 가정: 설정 키 이름 (스펙에 키 목록이 없어 정한 값)
const KEY_AUTO = '자산품목코드 자동부여';
const KEY_RULE = '자산품목코드 부여규칙';
const KEY_INSPECT = '자산검수조서 사용';
const USE = '사용';
const NOT_USE = '미사용';

@Controller('api/v1')
export class FnSfr02508Controller {
  @Get('/asset-config-settings')
  async listAssetConfigSettings(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const q = checks.queryOf(req.query);
    const page = Number(String(q['page'] ?? 0));
    const sizeRaw = Number(String(q['size'] ?? 20));
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
    }
    const size = Math.min(sizeRaw, 200);
    const area = q['settingArea'] ? String(q['settingArea']) : ASSET_AREA;
    return transaction(async (db) => {
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM config_setting WHERE setting_area = :area',
        { area },
      );
      const items = await db.query(
        'SELECT setting_key AS "settingKey", setting_value AS "settingValue", applied_from AS "appliedFrom" '
          + 'FROM config_setting WHERE setting_area = :area '
          + 'ORDER BY setting_key, applied_from DESC LIMIT :size OFFSET :offset',
        { area, size, offset: page * size },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Put('/asset-config-settings')
  async saveAssetConfigSettings(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const data = checks.inputOf(req.body);
    const key = typeof data['settingKey'] === 'string' ? data['settingKey'].trim() : '';
    const value = typeof data['settingValue'] === 'string' ? data['settingValue'].trim() : '';
    if (!key || key.length > 100) {
      throw new ApiError(400, 'VALIDATION_FAILED', '설정 항목 키를 확인해 주세요.');
    }
    if (!value || value.length > 1000) {
      throw new ApiError(400, 'VALIDATION_FAILED', '설정 값을 확인해 주세요.');
    }
    if (key !== KEY_AUTO && key !== KEY_RULE && key !== KEY_INSPECT) {
      throw new ApiError(400, 'VALIDATION_FAILED', '저장할 수 없는 설정 항목입니다.');
    }
    if ((key === KEY_AUTO || key === KEY_INSPECT) && value !== USE && value !== NOT_USE) {
      throw new ApiError(400, 'VALIDATION_FAILED', '사용 여부는 사용 또는 미사용으로 입력해 주세요.');
    }
    return transaction(async (db) => {
      if (key === KEY_AUTO && value === USE) {
        const rules = await db.query(
          'SELECT setting_value AS "settingValue" FROM config_setting '
            + 'WHERE setting_area = :area AND setting_key = :key ORDER BY applied_from DESC LIMIT 1',
          { area: ASSET_AREA, key: KEY_RULE },
        );
        const rule = rules.length > 0 ? String(rules[0]['settingValue'] ?? '').trim() : '';
        if (!rule) {
          throw new ApiError(422, 'CODE_RULE_REQUIRED', '자동부여를 사용하려면 부여 규칙을 먼저 입력해 주세요.');
        }
      }
      const before = await db.query(
        'SELECT setting_value AS "settingValue" FROM config_setting '
          + 'WHERE setting_area = :area AND setting_key = :key ORDER BY applied_from DESC LIMIT 1',
        { area: ASSET_AREA, key },
      );
      const saved = await db.query(
        'INSERT INTO config_setting (setting_area, setting_key, setting_value, applied_from, created_at, updated_at) '
          + 'VALUES (:area, :key, :value, CAST(now() AS date), now(), now()) '
          + 'ON CONFLICT (setting_area, setting_key, applied_from) '
          + 'DO UPDATE SET setting_value = EXCLUDED.setting_value, updated_at = now() '
          + 'RETURNING config_setting_id AS "configSettingId", setting_key AS "settingKey", '
          + 'setting_value AS "settingValue", applied_from AS "appliedFrom"',
        { area: ASSET_AREA, key, value },
      );
      const row = saved[0];
      const hasBefore = before.length > 0;
      await db.execute(
        'INSERT INTO change_history (target_type, target_id, change_type, changed_at, changer_id, '
          + 'before_content, after_content, created_at, updated_at) '
          + 'VALUES (:targetType, CAST(:targetId AS bigint), :changeType, now(), CAST(:userId AS bigint), '
          + ':beforeContent, :afterContent, now(), now())',
        {
          targetType: '환경설정',
          targetId: String(row['configSettingId']),
          changeType: hasBefore ? '수정' : '등록',
          userId: user.id,
          beforeContent: hasBefore ? String(before[0]['settingValue']) : null,
          afterContent: value,
        },
      );
      return {
        settingKey: row['settingKey'],
        settingValue: row['settingValue'],
        appliedFrom: row['appliedFrom'],
      };
    });
  }
}

