import { useState } from 'react';
import {
  call, useData, Filters, Band, DataTable, Pager, Drawer, Tiles, Form, Field,
  TextInput, Select, DateText, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const KEY_AUTO = '자산품목코드 자동부여';
const KEY_RULE = '자산품목코드 부여규칙';
const KEY_INSPECT = '자산검수조서 사용';
const KEY_OPTIONS: [string, string][] = [
  [KEY_AUTO, '자산품목코드 자동부여 여부'],
  [KEY_RULE, '자산품목코드 부여 규칙'],
  [KEY_INSPECT, '자산검수조서 사용 여부'],
];
const USE_OPTIONS: [string, string][] = [
  ['사용', '사용'],
  ['미사용', '미사용'],
];
const SIZE = 20;

export default function FnSfr02508Page({ role, notify }: PageProps) {
  const [area, setArea] = useState('');
  const [query, setQuery] = useState('');
  const [page, setPage] = useState(0);
  const [editing, setEditing] = useState(false);
  const [key, setKey] = useState('');
  const [value, setValue] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/asset-config-settings', role, undefined, { settingArea: query, page, size: SIZE }),
    [query, page],
  );
  const current = useData<Page>(
    () => call<Page>('GET', '/asset-config-settings', role, undefined, { page: 0, size: 200 }),
    [],
  );

  const latest = (k: string): string => {
    const found = (current.data?.items ?? []).find((r: Row) => r['settingKey'] === k);
    return found ? String(found['settingValue']) : '미설정';
  };

  const openEdit = (k: string, v: string) => {
    setKey(k);
    setValue(v);
    setEditing(true);
  };

  const submit = async () => {
    if (!key) throw new Error('설정 항목을 선택해 주세요.');
    if (!value.trim()) throw new Error('설정 값을 입력해 주세요.');
    await call('PUT', '/asset-config-settings', role, { settingKey: key, settingValue: value.trim() });
    notify('자산 기초환경설정을 저장했습니다.');
    setEditing(false);
    list.reload();
    current.reload();
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>현재 설정</h2>
        <Tiles
          items={[
            ['품목코드 자동부여', latest(KEY_AUTO)],
            ['부여 규칙', latest(KEY_RULE)],
            ['검수조서 사용', latest(KEY_INSPECT)],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>환경설정 목록</h2>
        <Filters
          onSearch={() => { setPage(0); setQuery(area); }}
          onReset={() => { setArea(''); setQuery(''); setPage(0); }}
        >
          <Field label="설정 영역">
            <TextInput value={area} onChange={setArea} placeholder="비우면 자산" />
          </Field>
        </Filters>
        <Band total={list.data?.total}>
          <button type="button" onClick={() => openEdit('', '')}>설정 저장</button>
        </Band>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          columns={[
            { key: 'settingKey', label: '설정 키' },
            { key: 'settingValue', label: '설정 값' },
            { key: 'appliedFrom', label: '적용 시작일', render: (r: Row) => <DateText value={r['appliedFrom']} /> },
            {
              key: 'action',
              label: '처리',
              render: (r: Row) => (
                <button type="button" onClick={() => openEdit(String(r['settingKey']), String(r['settingValue']))}>변경</button>
              ),
            },
          ]}
          rows={list.data?.items ?? []}
          empty="등록된 환경설정이 없습니다."
        />
        <Pager page={page} size={SIZE} total={list.data?.total ?? 0} onPage={setPage} />
      </section>
      {editing ? (
        <Drawer title="자산 기초환경설정 저장" onClose={() => setEditing(false)}>
          <Form
            onSubmit={submit}
            submit="저장"
            note="저장일 이후 등록 건부터 적용되며 기존 부여 코드는 변경되지 않습니다."
          >
            <Field label="설정 항목 키" required>
              <Select
                value={key}
                onChange={(v) => { setKey(v); setValue(''); }}
                options={KEY_OPTIONS}
              />
            </Field>
            <Field label="설정 값" required hint="자동부여를 사용하려면 부여 규칙을 먼저 저장해야 합니다.">
              {key === KEY_RULE ? (
                <TextInput value={value} onChange={setValue} />
              ) : (
                <Select value={value} onChange={setValue} options={USE_OPTIONS} />
              )}
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
